sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.heading-widget {
  text-align: center;
  padding: 30px;
  color: #ffffff;
  background: linear-gradient(135deg, #43cea2, #185a9d);
  border-radius: 20px;
  box-shadow: 0 10px 20px -5px rgba(0, 0, 0, 0.7);
  transform: translateY(0);
  transition: all 0.3s ease-in-out;
}

.heading-widget:hover {
  transform: translateY(-10px);
  box-shadow: 0 15px 30px -5px rgba(0, 0, 0, 0.9);
}

.heading-widget h1 {
  margin-bottom: 15px;
  font-size: 2.5em;
  letter-spacing: 1px;
  text-shadow: 2px 2px 4px black;
}

.heading-widget p {
  font-size: 1.3em;
  color: #ccffcc;
  margin-bottom: 0;
}

sp_widget.script:
(function() {
